  tarjetas:[['IDS vs IPS','IDS alerta; IPS bloquea (está en línea).'],['Detección por firmas','Patrones de ataques conocidos; no detecta lo nuevo.'],['Detección por anomalías','Desviaciones de lo normal; detecta lo nuevo con más falsos positivos.'],['HIDS','IDS instalado en un equipo.']],
